package com.arix.player;
import android.os.*;import android.net.Uri;import android.view.*;import android.widget.*;
public class VideoplayerActivity extends BaseActivity {private VideoView video;public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);LinearLayout r=new LinearLayout(this);r.setOrientation(1);r.setBackgroundColor(0xff000000);setContentView(r);video=new VideoView(this);r.addView(video,new LinearLayout.LayoutParams(-1,0,1));String u=link(getIntent());if(u.isEmpty()&&getIntent().getData()!=null)u=getIntent().getData().toString();if(!u.isEmpty()){video.setVideoURI(Uri.parse(u));MediaController c=new MediaController(this);video.setMediaController(c);c.setAnchorView(video);video.setOnPreparedListener(mp->video.start());video.setOnErrorListener((mp,w,e)->{new AlertDialog.Builder(this).setMessage("تعذر تشغيل الرابط. قد يحتاج إلى فك تشفير أو تنسيق مدعوم.").setPositiveButton("حسناً",(d,x)->finish()).show();return true;});}else r.addView(text("لم يتم تمرير رابط فيديو",18,0xffffffff,true),new LinearLayout.LayoutParams(-1,dp(90)));}protected void onPause(){super.onPause();if(video!=null&&video.isPlaying())video.pause();}}
